import base64
import hashlib
import json
import os
import secrets
import time
from dataclasses import dataclass
from typing import Any, Dict, Optional
from urllib.parse import urlencode

import requests


@dataclass
class PKCELoginResult:
    authorization_url: str
    state: str
    code_verifier: str
    code_challenge: str
    token_response: Optional[Dict[str, Any]] = None
    userinfo: Optional[Dict[str, Any]] = None


class Auth0PKCEClient:
    def __init__(
        self,
        domain: Optional[str] = None,
        client_id: Optional[str] = None,
        redirect_uri: Optional[str] = None,
        scope: str = "openid profile email",
        audience: Optional[str] = None,
    ) -> None:
        self.domain = domain or os.environ.get("AUTH0_DOMAIN")
        self.client_id = client_id or os.environ.get("AUTH0_CLIENT_ID")
        self.redirect_uri = redirect_uri or os.environ.get("AUTH0_REDIRECT_URI")
        self.scope = scope
        self.audience = audience or os.environ.get("AUTH0_AUDIENCE")
        if not self.domain:
            raise ValueError("AUTH0_DOMAIN is required")
        if not self.client_id:
            raise ValueError("AUTH0_CLIENT_ID is required")
        if not self.redirect_uri:
            raise ValueError("AUTH0_REDIRECT_URI is required")
        self.issuer = self._normalize_domain(self.domain)
        self.authorize_endpoint = f"https://{self.issuer}/authorize"
        self.token_endpoint = f"https://{self.issuer}/oauth/token"
        self.userinfo_endpoint = f"https://{self.issuer}/userinfo"

    @staticmethod
    def _normalize_domain(domain: str) -> str:
        domain = domain.strip()
        if domain.startswith("https://"):
            domain = domain[len("https://") :]
        elif domain.startswith("http://"):
            domain = domain[len("http://") :]
        return domain.rstrip("/")

    @staticmethod
    def _base64url_no_padding(data: bytes) -> str:
        return base64.urlsafe_b64encode(data).decode("ascii").rstrip("=")

    def generate_pkce_pair(self) -> Dict[str, str]:
        code_verifier = self._base64url_no_padding(secrets.token_bytes(32))
        code_challenge = self._base64url_no_padding(
            hashlib.sha256(code_verifier.encode("ascii")).digest()
        )
        return {"code_verifier": code_verifier, "code_challenge": code_challenge}

    def build_authorization_url(
        self,
        state: Optional[str] = None,
        code_challenge: Optional[str] = None,
        code_challenge_method: str = "S256",
        additional_params: Optional[Dict[str, str]] = None,
    ) -> PKCELoginResult:
        if state is None:
            state = self._base64url_no_padding(secrets.token_bytes(16))
        pkce = self.generate_pkce_pair()
        if code_challenge is None:
            code_challenge = pkce["code_challenge"]

        params = {
            "response_type": "code",
            "client_id": self.client_id,
            "redirect_uri": self.redirect_uri,
            "scope": self.scope,
            "state": state,
            "code_challenge": code_challenge,
            "code_challenge_method": code_challenge_method,
        }
        if self.audience:
            params["audience"] = self.audience
        if additional_params:
            params.update(additional_params)

        authorization_url = f"{self.authorize_endpoint}?{urlencode(params)}"
        return PKCELoginResult(
            authorization_url=authorization_url,
            state=state,
            code_verifier=pkce["code_verifier"],
            code_challenge=code_challenge,
        )

    def exchange_code_for_tokens(
        self,
        code: str,
        code_verifier: str,
    ) -> Dict[str, Any]:
        payload = {
            "grant_type": "authorization_code",
            "client_id": self.client_id,
            "code": code,
            "redirect_uri": self.redirect_uri,
            "code_verifier": code_verifier,
        }
        response = requests.post(self.token_endpoint, json=payload, timeout=30)
        response.raise_for_status()
        token_response = response.json()
        return token_response

    def fetch_userinfo(self, access_token: str) -> Dict[str, Any]:
        headers = {"Authorization": f"Bearer {access_token}"}
        response = requests.get(self.userinfo_endpoint, headers=headers, timeout=30)
        response.raise_for_status()
        return response.json()

    def complete_login_flow(
        self,
        authorization_code: str,
        code_verifier: str,
    ) -> PKCELoginResult:
        token_response = self.exchange_code_for_tokens(
            code=authorization_code,
            code_verifier=code_verifier,
        )
        access_token = token_response.get("access_token")
        userinfo = None
        if access_token:
            try:
                userinfo = self.fetch_userinfo(access_token)
            except requests.RequestException:
                userinfo = None

        return PKCELoginResult(
            authorization_url="",
            state="",
            code_verifier=code_verifier,
            code_challenge="",
            token_response=token_response,
            userinfo=userinfo,
        )
